// Local bilingual model notes; the viewer and device are unaffected.
const chinese = {"Approved nb1 mascot": "nb1 原有拟人形象", "Interactive model ↗": "交互模型 ↗", "Smooth joint, continuous light.": "平顺的交界，连续的混光。", "LED 1 is the blink(1) wordmark face; LED 2 is the ThingM face. The USB opening faces blink(1), and its black tongue faces ThingM. Camera rotation never swaps the LED identities.": "LED 1 是 blink(1) 字样面，LED 2 是 ThingM 商标面。USB 空腔朝向 blink(1)，黑色舌片朝向 ThingM；转动相机不交换灯号。", "Open 3D ↗": "打开 3D ↗", "View both faces ↗": "查看二维双面 ↗", "Integration reference ↗": "接入说明 ↗", "Physical reference": "用户实拍参考", "The metal and frosted plastic meet smoothly around the corners.": "金属和乳白塑料在圆角处平顺交接，没有向上刺入的尖齿。", "User-provided photograph of the blink(1) metal and plastic joint": "用户提供的blink(1)金属与塑料交界实拍参考", "Approved derived display model": "最终派生显示模型", "The unlit quarter view shows the visible joint. The original plastic geometry and wordmarks are preserved.": "熄灯斜视检查真实可见的接合轮廓，原塑料及字标不变。", "Approved Nightlab unlit USB quarter view with a smooth rounded joint": "最终Nightlab熄灯USB斜视，平顺的圆角交界", "USB end-on view": "USB 正视角", "Front and side occlusion were checked to keep internal metal behind the plastic surface. The reference records six poses, lit and unlit.": "前向和侧向遮挡均检查，避免内部金属三角面越到塑料外侧。保留六种姿态、亮灯与熄灯各一张。", "Approved lit USB end-on view, with green and red from the two fixed channels": "最终亮灯USB正视角，绿色与红色来自固定的两路目标", "Two-face fallback": "二维双面备用视图", "Both fixed faces remain visible while loading, without WebGL, and after context loss. Off and unspecified have distinct labels. Screen playback remains available.": "加载、无 WebGL 和上下文丢失时，继续分别显示两面。未指定和熄灭有不同标记；屏幕预览仍可播放。", "Nightlab two-face preview showing each fixed LED identity and color": "Nightlab二维双面预览，分别显示两路灯号和颜色", "Presentation contract": "继续开发时保留", "Continuous additive two-source light, independent diagnostic values, the actual Go playback plan, bounded zoom, ordinary scrolling, keyboard access, and reduced motion. Model captions keep safe insets and avoid the zoom controls.": "连续的两源线性混光、独立的诊断读数、实际 Go 计划播放、显式缩放、普通页面滚动、键盘与减少动态效果。模型左上文字保留安全内距，不与缩放控件重叠。", "Reference poses and screenshots": "实际姿态与截图记录", "Derived joint checks": "派生接合检查记录", "Historical physical LED identification": "灯号实物确认记录", "Sources and licenses": "来源与许可", "Official raw STL files are pinned to commit ": "官方原始 STL 固定于提交 ", ". Their bytes are preserved. The display assembly, supplemental USB geometry, and light field are visual approximations, not manufacturing or optical calibration files.": "，文件字节保留。显示装配、USB 补充几何和光效不是制造或光学校准文件。", "Sources and modifications": "分项来源与修改", "The illustration does not prove physical playback or replace hardware qualification.": "模拟图不证明实体灯正在运行，也不代替目标工程的硬件验收。"};
const entries = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) { const node = walker.currentNode; if (chinese[node.textContent]) entries.push([node, node.textContent]); }
const images = [...document.images].map(node => [node, node.alt]);
const button = document.getElementById('model-language');
button.addEventListener('click', () => {
  const zh = document.documentElement.lang !== 'zh-CN';
  document.documentElement.lang = zh ? 'zh-CN' : 'en';
  for (const [node, english] of entries) node.textContent = zh ? chinese[english] : english;
  for (const [node, english] of images) node.alt = zh ? chinese[english] || english : english;
  button.textContent = zh ? 'English' : '中文';
  button.setAttribute('aria-label', zh ? 'Switch to English' : 'Switch to Chinese');
});
